import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before cursor with INVALID_MESSAGE', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    const accepted = [
      {frame: {type: 'list_sessions'}, data: {type: 'list_sessions'}},
      {frame: {type: 'list_sessions', limit: 10}, data: {type: 'list_sessions', limit: 10}},
      {frame: {type: 'list_sessions', before}, data: {type: 'list_sessions', before}},
      {
        frame: {type: 'list_sessions', limit: 0, before: {updatedAt: 1767225600000, sessionId: 's1'}},
        data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1767225600000, sessionId: 's1'}},
      },
      // userId is no frame of the client's to set: the validator strips it, so no caller after it can read it.
      {
        frame: {type: 'list_sessions', limit: 10, before, userId: 'u2'},
        data: {type: 'list_sessions', limit: 10, before},
      },
    ];
    expect(accepted.map(({frame}) => validateMessage(frame))).toEqual(accepted.map(({data}) => ({valid: true, data})));

    const rejected: Array<[unknown, string]> = [
      [{type: 'list_sessions', limit: 'ten'}, 'limit'],
      [{type: 'list_sessions', limit: -1}, 'limit'],
      [{type: 'list_sessions', limit: 1.5}, 'limit'],
      [{type: 'list_sessions', before: 'not-an-object'}, 'before'],
      [{type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z'}}, 'sessionId'],
      [{type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}, 'sessionId'],
      [
        {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
        'sessionId',
      ],
      [{type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}, 'updatedAt'],
      [{type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}, 'updatedAt'],
    ];
    for (const [frame, field] of rejected) {
      const result = validateMessage(frame);
      expect(result.valid).toBe(false);
      if (!result.valid) expect(result.error).toContain(field);
    }
  });
});

