// Answered off the turn lock: a history request is not a turn and mutates nothing, so it never queues behind a stream.
async function handleListSessions(
  ws: WebSocket,
  userId: string | number,
  message: ListSessionsMessage,
  sessionStore: SessionStore | undefined
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(userId, {limit: message.limit, before: message.before})) ?? [];
    sendJson(ws, {type: 'session_list', sessions: summaries.map(summaryFrame)});
  } catch (error) {
    // Named on the ws category, where a consumer's connection alerts live, and carrying the user id, not the user's data.
    log.error('ws', 'listing conversations failed', {userId, error: message of error});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

// Dates do not survive JSON as Dates, so the wire frame carries them as ISO strings.
function summaryFrame({sessionId, createdAt, updatedAt, entryCount}: SessionSummary): SessionSummaryFrame {
  return {sessionId, createdAt: createdAt.toISOString(), updatedAt: updatedAt.toISOString(), entryCount};
}
